//! Running one test: find the gateway, run, clean up.

use std::panic::AssertUnwindSafe;

use futures::FutureExt;

use crate::cli::Cli;
use crate::context::Context;
use crate::error::Result;
use crate::gateway::Gateway;

/// Identity of a test, generated by `#[testkit::test]`.
#[derive(Clone, Copy, Debug)]
pub struct TestInfo {
    /// The function name, which is also the nextest test name.
    pub name: &'static str,
    pub description: &'static str,
}

/// Run a test body against the gateway found by [`Gateway::from_env`].
///
/// Cleanup runs whether the body passes, fails, or panics. The test fails if
/// the body fails, or if cleanup fails after the body passed.
///
/// # Panics
///
/// Panics to fail the test.
pub async fn run<F>(info: TestInfo, body: F)
where
    F: AsyncFnOnce(&mut Context) -> Result,
{
    let name = info.name;
    eprintln!("[{name}] {}", info.description);

    let gateway = Gateway::from_env().unwrap_or_else(|error| panic!("[{name}] {error}"));
    eprintln!("[{name}] {}", gateway.describe());
    let client = gateway
        .connect()
        .await
        .unwrap_or_else(|error| panic!("[{name}] {error}"));
    let mut cx = Context::new(&client, &gateway.workspace, Cli::from_env(&gateway));
    eprintln!("[{name}] run id {}", cx.run_id());

    let outcome = AssertUnwindSafe(body(&mut cx)).catch_unwind().await;
    let cleanup_failures = cx.cleanup().await;
    for failure in &cleanup_failures {
        eprintln!("[{name}] cleanup failed: {failure}");
    }

    match outcome {
        Err(panic) => std::panic::resume_unwind(panic),
        Ok(Err(error)) => panic!("[{name}] {error}"),
        Ok(Ok(())) => assert!(
            cleanup_failures.is_empty(),
            "[{name}] passed, but cleanup failed: {}",
            cleanup_failures.join("; ")
        ),
    }
}
